	// Create a .env with two keys.
	dir := t.TempDir()
	envPath := filepath.Join(dir, ".env")
	contents := "BOOTENV_TEST_NEW=from-file\nBOOTENV_TEST_PRESET=from-file\n"
	if err := os.WriteFile(envPath, []byte(contents), 0o600); err != nil {
		t.Fatal(err)
	}

